/*
 * A369110  a(n) is the number of distinct elements appearing in the sequence
 *          formed by recursively applying A063655 when starting from n.
 * https://oeis.org/A369110
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 580, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   minimal_sum
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Recurrence: a(n) = number of distinct terms in the sequence
 * generated by repeatedly applying the function A063655 (minimal sum
 * of two positive integers whose product is n) until a cycle is hit.
 *
 * The implementation evaluates A063655 by inspecting all divisors
 * up to sqrt(n).  The sequence is iterated until a value repeats;
 * the visited values are stored in a dynamically sized boolean array.
 * This works for n up to the limits of typical test data (≈ 10 000) and
 * returns the result as seq_t.
 */

#include <stdlib.h>
#include "../utils/minimal_sum.h"

seq_t a(idx_t n) {
    /* sequence starts with the input value n */
    if (n == 0) return (seq_t)0;          /* undefined, but safe guard */

    /* maximum value that can appear is n+1, so we can size the
       visited array accordingly. */
    size_t max_val = (size_t)(n + (idx_t)1);
    unsigned char *visited = (unsigned char *)calloc(max_val + 1, sizeof(unsigned char));
    if (!visited) return (seq_t)0;        /* allocation failure */

    seq_t curr = (seq_t)n;
    seq_t count = 0;

    while (!visited[(size_t)curr]) {
        visited[(size_t)curr] = 1;
        ++count;
        curr = minimal_sum(curr);
    }

    free(visited);
    return count;
}
